export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-9\",\"workId\":\"xunzi\",\"order\":9,\"title\":\"王制\",\"difficulty\":4,\"estimatedMinutes\":17,\"passageIds\":[\"xunzi_ch-9_p-1\",\"xunzi_ch-9_p-2\",\"xunzi_ch-9_p-3\",\"xunzi_ch-9_p-4\",\"xunzi_ch-9_p-5\",\"xunzi_ch-9_p-6\",\"xunzi_ch-9_p-7\",\"xunzi_ch-9_p-8\",\"xunzi_ch-9_p-9\",\"xunzi_ch-9_p-10\",\"xunzi_ch-9_p-11\",\"xunzi_ch-9_p-12\",\"xunzi_ch-9_p-13\",\"xunzi_ch-9_p-14\",\"xunzi_ch-9_p-15\",\"xunzi_ch-9_p-16\",\"xunzi_ch-9_p-17\",\"xunzi_ch-9_p-18\",\"xunzi_ch-9_p-19\",\"xunzi_ch-9_p-20\",\"xunzi_ch-9_p-21\",\"xunzi_ch-9_p-22\",\"xunzi_ch-9_p-23\",\"xunzi_ch-9_p-24\",\"xunzi_ch-9_p-25\",\"xunzi_ch-9_p-26\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-9_p-1\",\"chapterId\":\"xunzi_ch-9\",\"order\":1,\"canonicalText\":\"請問為政？曰：賢能不待次而舉，罷不能不待須而廢，元惡不待教而誅，中庸雜民不待政而化。分未定也，則有昭繆也。雖王公士大夫之子孫也，不能屬於禮義，則歸之庶人。雖庶人之子孫也，積文學，正身行，能屬於禮義，則歸之卿相士大夫。故姦言，姦說，姦事，姦能，遁逃反側之民，職而教之，須而待之，勉之以慶賞，懲之以刑罰。安職則畜，不安職則棄。五疾，上收而養之，材而事之，官施而衣食之，兼覆無遺。纔行反時者死無赦。夫是之謂天德，是王者之政也。\",\"sentenceIds\":[\"xunzi_ch-9_p-1_s-1\",\"xunzi_ch-9_p-1_s-2\",\"xunzi_ch-9_p-1_s-3\",\"xunzi_ch-9_p-1_s-4\",\"xunzi_ch-9_p-1_s-5\",\"xunzi_ch-9_p-1_s-6\",\"xunzi_ch-9_p-1_s-7\",\"xunzi_ch-9_p-1_s-8\",\"xunzi_ch-9_p-1_s-9\",\"xunzi_ch-9_p-1_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 1 節）中論述道：請問為政？說道：：賢能不待次而且舉，罷不能不待須而且廢，元惡不待教而且誅，中庸雜民不待政而且化。分未定啊，則有昭繆啊。雖王公士大夫的子孫啊，不能屬於禮正義道義道品德修養規程正義道義，則歸的庶人。雖庶人的子孫啊，積文學，正身行，能屬於禮正義道義道品德修養規程正義道義，則歸的卿相士大夫。所以姦言，姦說，姦事，姦能，遁逃反側的民，職而且教的，須而且待的，勉的以慶賞，懲的以刑罰。安職則畜，不安職則棄。五疾，上收而且養的，材而且事的，官施而且衣食的，兼覆無遺。纔行反時的人或事物死無赦。這就是儒家所稱的天品德修養，是王的人或事物的政啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「請問為政」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「請問為政？曰：賢能不待次而舉，罷不能不待須而廢，元惡……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-2\",\"chapterId\":\"xunzi_ch-9\",\"order\":2,\"canonicalText\":\"聽政之大分：以善至者待之以禮，以不善至者待之以刑。兩者分別，則賢不肖不雜，是非不亂。賢不肖不雜，則英傑至，是非不亂，則國家治。若是，名聲日聞，天下願，令行禁止，王者之事畢矣。\",\"sentenceIds\":[\"xunzi_ch-9_p-2_s-1\",\"xunzi_ch-9_p-2_s-2\",\"xunzi_ch-9_p-2_s-3\",\"xunzi_ch-9_p-2_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 2 節）中論述道：聽政的大分：以善至的人或事物待的以禮正義道義道品德修養規程，以不善至的人或事物待的以刑。兩的人或事物分別，則賢不肖不雜，是絕不是不亂。賢不肖不雜，則英傑至，是絕不是不亂，則國家治。若是，名聲日聞，天下願，令行禁止，王的人或事物的事畢矣。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「聽政之大分：以善至者待之以禮，以不善至者待之以刑」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「聽政之大分：以善至者待之以禮，以不善至者待之以刑。兩……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-3\",\"chapterId\":\"xunzi_ch-9\",\"order\":3,\"canonicalText\":\"凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭。若是，則大事殆乎弛，小事殆乎遂。和解調通，好假道人，而無所凝止之，則姦言並至，嘗試之說鋒起。若是，則聽大事煩，是又傷之也。故法而不議，則法之所不至者必廢。職而不通，則職之所不及者必隊。故法而議，職而通，無隱謀，無遺善，而百事無過，非君子莫能。故公平者，聽1之衡也；中和者，聽之繩也。其有法者以法行，無法者以類舉，聽之盡也。偏黨而不經，聽之闢也。故有良法而亂者，有之矣，有君子而亂者，自古及今，未嘗聞也。傳曰：「治生乎君子，亂生乎小人。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-9_p-3_s-1\",\"xunzi_ch-9_p-3_s-2\",\"xunzi_ch-9_p-3_s-3\",\"xunzi_ch-9_p-3_s-4\",\"xunzi_ch-9_p-3_s-5\",\"xunzi_ch-9_p-3_s-6\",\"xunzi_ch-9_p-3_s-7\",\"xunzi_ch-9_p-3_s-8\",\"xunzi_ch-9_p-3_s-9\",\"xunzi_ch-9_p-3_s-10\",\"xunzi_ch-9_p-3_s-11\",\"xunzi_ch-9_p-3_s-12\",\"xunzi_ch-9_p-3_s-13\",\"xunzi_ch-9_p-3_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 3 節）中論述道：凡聽：威嚴猛厲，而且不好假道人，則下畏恐而且不親，周閉而且不竭。若是，則大事殆乎弛，小事殆乎遂。和解調通，好假道人，而且無所凝止的，則姦言並至，嘗試的說鋒起。若是，則聽大事煩，是又傷的啊。所以國家典章法度而且不議，則國家典章法度的所不至的人或事物必廢。職而且不通，則職的所不及的人或事物必隊。所以國家典章法度而且議，職而且通，無隱謀，無遺善，而且百事無過，絕不是君子莫能。所以公平的人或事物，聽1的衡啊；中和的人或事物，聽的繩啊。他的有國家典章法度的人或事物以國家典章法度行，無國家典章法度的人或事物以類舉，聽的盡啊。偏黨而且不經，聽的闢啊。所以有良國家典章法度而且亂的人或事物，有的矣，有君子而且亂的人或事物，自古及今，未嘗聞啊。傳說道：：治生乎君子，亂生乎小人。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-4\",\"chapterId\":\"xunzi_ch-9\",\"order\":4,\"canonicalText\":\"分均則不偏，埶齊則不壹，眾齊則不使。有天有地，而上下有差；明王始立，而處國有制。夫兩貴之不能相事，兩賤之不能相使，是天數也。埶位齊，而欲惡同，物不能澹則必爭；爭則必亂，亂則窮矣。先王惡其亂也，故制禮義以分之，使有貧富貴賤之等，足以相兼臨者，是養天下之本也。《書》曰：「維齊非齊。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-9_p-4_s-1\",\"xunzi_ch-9_p-4_s-2\",\"xunzi_ch-9_p-4_s-3\",\"xunzi_ch-9_p-4_s-4\",\"xunzi_ch-9_p-4_s-5\",\"xunzi_ch-9_p-4_s-6\",\"xunzi_ch-9_p-4_s-7\",\"xunzi_ch-9_p-4_s-8\",\"xunzi_ch-9_p-4_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 4 節）中論述道：分均則不偏，埶齊則不壹，眾齊則不使。有天有地，而且上下有差；明王始立，而且處國有制。夫兩貴的不能相事，兩賤的不能相使，是天數啊。埶位齊，而且欲惡同，物不能澹則必爭；爭則必亂，亂則窮矣。先王惡他的亂啊，所以制禮正義道義道品德修養規程正義道義以分的，使有貧富貴賤的等，足以相兼臨的人或事物，是養天下的本啊。《書》說道：：維齊絕不是齊。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「分均則不偏，埶齊則不壹，眾齊則不使」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「分均則不偏，埶齊則不壹，眾齊則不使。有天有地，而上下……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-5\",\"chapterId\":\"xunzi_ch-9\",\"order\":5,\"canonicalText\":\"馬駭輿，則君子不安輿；庶人駭政，則君子不安位。馬駭輿，則莫若靜之；庶人駭政，則莫若惠之。選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。如是，則庶人安政矣。庶人安政，然後君子安位。傳曰：「君者、舟也，庶人者、水也；水則載舟，水則覆舟。」此之謂也。故君人者，欲安、則莫若平政愛民矣；欲榮、則莫若隆禮敬士矣；欲立功名、則莫若尚賢使能矣。－是人君之大節也。三節者當，則其餘莫不當矣。三節者不當，則其餘雖曲當，猶將無益也。孔子曰：「大節是也，小節是也，上君也；大節是也，小節一齣焉，一入焉，中君也；大節非也，小節雖是也，吾無觀其餘矣。」\",\"sentenceIds\":[\"xunzi_ch-9_p-5_s-1\",\"xunzi_ch-9_p-5_s-2\",\"xunzi_ch-9_p-5_s-3\",\"xunzi_ch-9_p-5_s-4\",\"xunzi_ch-9_p-5_s-5\",\"xunzi_ch-9_p-5_s-6\",\"xunzi_ch-9_p-5_s-7\",\"xunzi_ch-9_p-5_s-8\",\"xunzi_ch-9_p-5_s-9\",\"xunzi_ch-9_p-5_s-10\",\"xunzi_ch-9_p-5_s-11\",\"xunzi_ch-9_p-5_s-12\",\"xunzi_ch-9_p-5_s-13\",\"xunzi_ch-9_p-5_s-14\",\"xunzi_ch-9_p-5_s-15\",\"xunzi_ch-9_p-5_s-16\",\"xunzi_ch-9_p-5_s-17\",\"xunzi_ch-9_p-5_s-18\",\"xunzi_ch-9_p-5_s-19\",\"xunzi_ch-9_p-5_s-20\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 5 節）中論述道：馬駭輿，則君子不安輿；庶人駭政，則君子不安位。馬駭輿，則莫若靜的；庶人駭政，則莫若惠的。選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。如是，則庶人安政矣。庶人安政，然後君子安位。傳說道：：君的人或事物、舟啊，庶人的人或事物、水啊；水則載舟，水則覆舟。此的謂啊。所以君人的人或事物，欲安、則莫若平政愛民矣；欲榮、則莫若隆禮正義道義道品德修養規程敬士矣；欲立功名、則莫若尚賢使能矣。－是人君的大節啊。三節的人或事物當，則他的餘莫不當矣。三節的人或事物不當，則他的餘雖曲當，猶將無益啊。孔子說道：：大節是啊，小節是啊，上君啊；大節是啊，小節一齣焉，一入焉，中君啊；大節絕不是啊，小節雖是啊，吾無觀他的餘矣。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「馬駭輿，則君子不安輿」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「馬駭輿，則君子不安輿；庶人駭政，則君子不安位。馬駭輿……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-6\",\"chapterId\":\"xunzi_ch-9\",\"order\":6,\"canonicalText\":\"成侯、嗣公聚斂計數之君也，未及取民也。子產取民者也，未及為政也。管仲為政者也，未及修禮也。故修禮者王，為政者彊，取民者安，聚斂者亡。故王者富民，霸者富士，僅存之國富大夫，亡國富筐篋，實府庫。筐篋已富，府庫已實，而百姓貧：夫是之謂上溢而下漏。入不可以守，出不可以戰，則傾覆滅亡可立而待也。故我聚之以亡，敵得之以彊。聚斂者，召寇、肥敵、亡國、危身之道也，故明君不蹈也。\",\"sentenceIds\":[\"xunzi_ch-9_p-6_s-1\",\"xunzi_ch-9_p-6_s-2\",\"xunzi_ch-9_p-6_s-3\",\"xunzi_ch-9_p-6_s-4\",\"xunzi_ch-9_p-6_s-5\",\"xunzi_ch-9_p-6_s-6\",\"xunzi_ch-9_p-6_s-7\",\"xunzi_ch-9_p-6_s-8\",\"xunzi_ch-9_p-6_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 6 節）中論述道：成侯、嗣公聚斂計數的君啊，未及取民啊。子產取民的人或事物啊，未及為政啊。管仲為政的人或事物啊，未及修禮正義道義道品德修養規程啊。所以修禮正義道義道品德修養規程的人或事物王，為政的人或事物彊，取民的人或事物安，聚斂的人或事物亡。所以王的人或事物富民，霸的人或事物富士，僅存的國富大夫，亡國富筐篋，實府庫。筐篋已富，府庫已實，而且百姓貧：這就是儒家所稱的上溢而且下漏。入不可以守，出不可以戰，則傾覆滅亡可立而且待啊。所以我聚的以亡，敵得的以彊。聚斂的人或事物，召寇、肥敵、亡國、危身的道啊，所以明君不蹈啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「成侯、嗣公聚斂計數之君也，未及取民也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「成侯、嗣公聚斂計數之君也，未及取民也。子產取民者也，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-7\",\"chapterId\":\"xunzi_ch-9\",\"order\":7,\"canonicalText\":\"王奪之人，霸奪之與，彊奪之地。奪之人者臣諸侯，奪之與者友諸侯，奪之地者敵諸侯。臣諸侯者王，友諸侯者霸，敵諸侯者危。\",\"sentenceIds\":[\"xunzi_ch-9_p-7_s-1\",\"xunzi_ch-9_p-7_s-2\",\"xunzi_ch-9_p-7_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 7 節）中論述道：王奪的人，霸奪的與，彊奪的地。奪的人的人或事物臣諸侯，奪的與的人或事物友諸侯，奪的地的人或事物敵諸侯。臣諸侯的人或事物王，友諸侯的人或事物霸，敵諸侯的人或事物危。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王奪之人，霸奪之與，彊奪之地」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王奪之人，霸奪之與，彊奪之地。奪之人者臣諸侯，奪之與……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-8\",\"chapterId\":\"xunzi_ch-9\",\"order\":8,\"canonicalText\":\"用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣；傷人之民甚，則人之民必惡我甚矣；人之民惡我甚，則日欲與我鬥。人之城守，人之出戰，而我以力勝之，則傷吾民必甚矣；傷吾民甚，則吾民之惡我必甚矣；吾民之惡我甚，則日不欲為我鬥。人之民日欲與我鬥，吾民日不欲為我鬥，是彊者之所以反弱也。地來而民去，累多而功少，雖守者益，所以守者損，是以大者之所以反削也。諸侯莫不懷交接怨，而不忘其敵，伺彊大之間，承彊大之敝，此彊大之殆時也。\",\"sentenceIds\":[\"xunzi_ch-9_p-8_s-1\",\"xunzi_ch-9_p-8_s-2\",\"xunzi_ch-9_p-8_s-3\",\"xunzi_ch-9_p-8_s-4\",\"xunzi_ch-9_p-8_s-5\",\"xunzi_ch-9_p-8_s-6\",\"xunzi_ch-9_p-8_s-7\",\"xunzi_ch-9_p-8_s-8\",\"xunzi_ch-9_p-8_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 8 節）中論述道：用彊的人或事物：人的城守，人的出戰，而且我以力勝的啊，則傷人的民必甚矣；傷人的民甚，則人的民必惡我甚矣；人的民惡我甚，則日欲與我鬥。人的城守，人的出戰，而且我以力勝的，則傷吾民必甚矣；傷吾民甚，則吾民的惡我必甚矣；吾民的惡我甚，則日不欲為我鬥。人的民日欲與我鬥，吾民日不欲為我鬥，是彊的人或事物的所以反弱啊。地來而且民去，累多而且功少，雖守的人或事物益，所以守的人或事物損，是以大的人或事物的所以反削啊。諸侯莫不懷交接怨，而且不忘他的敵，伺彊大的間，承彊大的敝，此彊大的殆時啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-9\",\"chapterId\":\"xunzi_ch-9\",\"order\":9,\"canonicalText\":\"知彊大者不務彊也，慮以王命，全其力，凝其德。力全則諸侯不能弱也，德凝則諸侯不能削也，天下無王霸主，則常勝矣：是知彊道者也。\",\"sentenceIds\":[\"xunzi_ch-9_p-9_s-1\",\"xunzi_ch-9_p-9_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 9 節）中論述道：知彊大的人或事物不務彊啊，慮以王命，全他的力，凝他的品德修養。力全則諸侯不能弱啊，品德修養凝則諸侯不能削啊，天下無王霸主，則常勝矣：是知彊道的人或事物啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「知彊大者不務彊也，慮以王命，全其力，凝其德」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「知彊大者不務彊也，慮以王命，全其力，凝其德。力全則諸……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-10\",\"chapterId\":\"xunzi_ch-9\",\"order\":10,\"canonicalText\":\"彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之。存亡繼絕，衛弱禁暴，而無兼併之心，則諸侯親之矣。修友敵之道，以敬接諸侯，則諸侯說之矣。所以親之者，以不併也；並之見，則諸侯疏矣。所以說之者，以友敵也；臣之見，則諸侯離矣。故明其不併之行，信其友敵之道，天下無王霸主，則常勝矣。是知霸道者也。\",\"sentenceIds\":[\"xunzi_ch-9_p-10_s-1\",\"xunzi_ch-9_p-10_s-2\",\"xunzi_ch-9_p-10_s-3\",\"xunzi_ch-9_p-10_s-4\",\"xunzi_ch-9_p-10_s-5\",\"xunzi_ch-9_p-10_s-6\",\"xunzi_ch-9_p-10_s-7\",\"xunzi_ch-9_p-10_s-8\",\"xunzi_ch-9_p-10_s-9\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 10 節）中論述道：彼霸的人或事物則不然：闢田野，實倉廩，便備用，案謹募選閱材伎的士，然後漸慶賞以先的，嚴刑罰以糾的。存亡繼絕，衛弱禁暴，而且無兼併的心，則諸侯親的矣。修友敵的道，以敬接諸侯，則諸侯說的矣。所以親的的人或事物，以不併啊；並的見，則諸侯疏矣。所以說的的人或事物，以友敵啊；臣的見，則諸侯離矣。所以明他的不併的行，信他的友敵的道，天下無王霸主，則常勝矣。是知霸道的人或事物啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-11\",\"chapterId\":\"xunzi_ch-9\",\"order\":11,\"canonicalText\":\"閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也。\",\"sentenceIds\":[\"xunzi_ch-9_p-11_s-1\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 11 節）中論述道：閔王毀於五國，桓公劫於魯莊，無它所以焉，絕不是他的道而且慮的以王啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-12\",\"chapterId\":\"xunzi_ch-9\",\"order\":12,\"canonicalText\":\"彼王者不然：仁眇天下，義眇天下，威眇天下。仁眇天下，故天下莫不親也；義眇天下，故天下莫不貴也；威眇天下，故天下莫敢敵也。以不敵之威，輔服人之道，故不戰而勝，不攻而得，甲兵不勞而天下服，是知王道者也。知此三具者，欲王而王，欲霸而霸，欲彊而彊矣。\",\"sentenceIds\":[\"xunzi_ch-9_p-12_s-1\",\"xunzi_ch-9_p-12_s-2\",\"xunzi_ch-9_p-12_s-3\",\"xunzi_ch-9_p-12_s-4\",\"xunzi_ch-9_p-12_s-5\",\"xunzi_ch-9_p-12_s-6\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 12 節）中論述道：彼王的人或事物不然：仁愛慈悲之德眇天下，正義道義眇天下，威眇天下。仁愛慈悲之德眇天下，所以天下莫不親啊；正義道義眇天下，所以天下莫不貴啊；威眇天下，所以天下莫敢敵啊。以不敵的威，輔服人的道，所以不戰而且勝，不攻而且得，甲兵不勞而且天下服，是知王道的人或事物啊。知此三具的人或事物，欲王而且王，欲霸而且霸，欲彊而且彊矣。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「彼王者不然：仁眇天下，義眇天下，威眇天下」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「彼王者不然：仁眇天下，義眇天下，威眇天下。仁眇天下，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-13\",\"chapterId\":\"xunzi_ch-9\",\"order\":13,\"canonicalText\":\"王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原。是王者之人也。\",\"sentenceIds\":[\"xunzi_ch-9_p-13_s-1\",\"xunzi_ch-9_p-13_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 13 節）中論述道：王的人或事物的人：飾動以禮正義道義道品德修養規程正義道義，聽斷以類，明振毫末，舉措應變而且不窮，這就是儒家所稱的有原。是王的人或事物的人啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-14\",\"chapterId\":\"xunzi_ch-9\",\"order\":14,\"canonicalText\":\"王者之制：道不過三代，法不二後王；道過三代謂之蕩，法二後王謂之不雅。衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。聲、則非雅聲者舉廢，色、則凡非舊文者舉息，械用，則凡非舊器者舉毀，夫是之謂復古，是王者之制也。\",\"sentenceIds\":[\"xunzi_ch-9_p-14_s-1\",\"xunzi_ch-9_p-14_s-2\",\"xunzi_ch-9_p-14_s-3\",\"xunzi_ch-9_p-14_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 14 節）中論述道：王的人或事物的制：道不過三代，國家典章法度不二後王；道過三代謂的蕩，國家典章法度二後王謂的不雅。衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。聲、則絕不是雅聲的人或事物舉廢，色、則凡絕不是舊文的人或事物舉息，械用，則凡絕不是舊器的人或事物舉毀，這就是儒家所稱的復古，是王的人或事物的制啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王者之制：道不過三代，法不二後王」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王者之制：道不過三代，法不二後王；道過三代謂之蕩，法……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-15\",\"chapterId\":\"xunzi_ch-9\",\"order\":15,\"canonicalText\":\"王者之論：無德不貴，無能不官，無功不賞，無罪不罰。朝無幸位，民無幸生。尚賢使能，而等位不遺；析願禁悍，而刑罰不過。百姓曉然皆知夫為善於家，而取賞於朝也；為不善於幽，而蒙刑於顯也。夫是之謂定論。是王者之論也。\",\"sentenceIds\":[\"xunzi_ch-9_p-15_s-1\",\"xunzi_ch-9_p-15_s-2\",\"xunzi_ch-9_p-15_s-3\",\"xunzi_ch-9_p-15_s-4\",\"xunzi_ch-9_p-15_s-5\",\"xunzi_ch-9_p-15_s-6\",\"xunzi_ch-9_p-15_s-7\",\"xunzi_ch-9_p-15_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 15 節）中論述道：王的人或事物的論：無品德修養不貴，無能不官，無功不賞，無罪不罰。朝無幸位，民無幸生。尚賢使能，而且等位不遺；析願禁悍，而且刑罰不過。百姓曉然皆知夫為善於家，而且取賞於朝啊；為不善於幽，而且蒙刑於顯啊。這就是儒家所稱的定論。是王的人或事物的論啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王者之論：無德不貴，無能不官，無功不賞，無罪不罰」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王者之論：無德不貴，無能不官，無功不賞，無罪不罰。朝……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-16\",\"chapterId\":\"xunzi_ch-9\",\"order\":16,\"canonicalText\":\"王者之法1：等賦、政事、財萬物，所以養萬民也。田野什一，關市幾而不徵，山林澤梁，以時禁發而不稅。相地而衰政。理道之遠近而致貢。通流財物粟米，無有滯留，使相歸移也，四海之內若一家。故近者不隱其能，遠者不疾其勞，無幽閒隱僻之國，莫不趨使而安樂之。夫是之為人師。是王者之法也。\",\"sentenceIds\":[\"xunzi_ch-9_p-16_s-1\",\"xunzi_ch-9_p-16_s-2\",\"xunzi_ch-9_p-16_s-3\",\"xunzi_ch-9_p-16_s-4\",\"xunzi_ch-9_p-16_s-5\",\"xunzi_ch-9_p-16_s-6\",\"xunzi_ch-9_p-16_s-7\",\"xunzi_ch-9_p-16_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 16 節）中論述道：王的人或事物的國家典章法度1：等賦、政事、財萬物，所以養萬民啊。田野什一，關市幾而且不徵，山林澤梁，以時禁發而且不稅。相地而且衰政。理道的遠近而且致貢。通流財物粟米，無有滯留，使相歸移啊，四海的內若一家。所以近的人或事物不隱他的能，遠的人或事物不疾他的勞，無幽閒隱僻的國，莫不趨使而且安樂的。夫是的為人師。是王的人或事物的國家典章法度啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「王者之法1：等賦、政事、財萬物，所以養萬民也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「王者之法1：等賦、政事、財萬物，所以養萬民也。田野什……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-17\",\"chapterId\":\"xunzi_ch-9\",\"order\":17,\"canonicalText\":\"北海則有走馬吠犬焉，然而中國得而畜使之。南海則有羽翮、齒革、曾青、丹干焉，然而中國得而財之。東海則有紫紶、魚鹽焉，然而中國得而衣食之。西海則有皮革、文旄焉，然而中國得而用之。故澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而足械用，工賈不耕田而足菽粟。故虎豹為猛矣，然君子剝而用之。故天之所覆，地之所載，莫不盡其美，致其用，上以飾賢良，下以養百姓而安樂之。夫是之謂大神。《詩》曰：「天作高山，大王荒之；彼作矣，文王康之。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-9_p-17_s-1\",\"xunzi_ch-9_p-17_s-2\",\"xunzi_ch-9_p-17_s-3\",\"xunzi_ch-9_p-17_s-4\",\"xunzi_ch-9_p-17_s-5\",\"xunzi_ch-9_p-17_s-6\",\"xunzi_ch-9_p-17_s-7\",\"xunzi_ch-9_p-17_s-8\",\"xunzi_ch-9_p-17_s-9\",\"xunzi_ch-9_p-17_s-10\",\"xunzi_ch-9_p-17_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 17 節）中論述道：北海則有走馬吠犬焉，然而且中國得而且畜使的。南海則有羽翮、齒革、曾青、丹干焉，然而且中國得而且財的。東海則有紫紶、魚鹽焉，然而且中國得而且衣食的。西海則有皮革、文旄焉，然而且中國得而且用的。所以澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而且足械用，工賈不耕田而且足菽粟。所以虎豹為猛矣，然君子剝而且用的。所以天的所覆，地的所載，莫不盡他的美，致他的用，上以飾賢良，下以養百姓而且安樂的。這就是儒家所稱的大神。《詩》說道：：天作高山，大王荒的；彼作矣，文王康的。此的謂啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「北海則有走馬吠犬焉，然而中國得而畜使之」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「北海則有走馬吠犬焉，然而中國得而畜使之。南海則有羽翮……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-18\",\"chapterId\":\"xunzi_ch-9\",\"order\":18,\"canonicalText\":\"以類行雜，以一行萬。始則終，終則始，若環之無端也，舍是而天下以衰矣。天地者，生之始也；禮義者，治之始也；君子者，禮義之始也；為之，貫之，積重之，致好之者，君子之始也。故天地生君子，君子理天地；君子者，天地之參也，萬物之摠也，民之父母也。無君子，則天地不理，禮義無統，上無君師，下無父子、夫婦，是之謂至亂。君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，夫是之謂大本。故喪祭、朝聘、師旅一也；貴賤、殺生、與奪一也；君君、臣臣、父父、子子、兄兄、弟弟一也；農農、士士、工工、商商一也。\",\"sentenceIds\":[\"xunzi_ch-9_p-18_s-1\",\"xunzi_ch-9_p-18_s-2\",\"xunzi_ch-9_p-18_s-3\",\"xunzi_ch-9_p-18_s-4\",\"xunzi_ch-9_p-18_s-5\",\"xunzi_ch-9_p-18_s-6\",\"xunzi_ch-9_p-18_s-7\",\"xunzi_ch-9_p-18_s-8\",\"xunzi_ch-9_p-18_s-9\",\"xunzi_ch-9_p-18_s-10\",\"xunzi_ch-9_p-18_s-11\",\"xunzi_ch-9_p-18_s-12\",\"xunzi_ch-9_p-18_s-13\",\"xunzi_ch-9_p-18_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 18 節）中論述道：以類行雜，以一行萬。始則終，終則始，若環的無端啊，舍是而且天下以衰矣。天地的人或事物，生的始啊；禮正義道義道品德修養規程正義道義的人或事物，治的始啊；君子的人或事物，禮正義道義道品德修養規程正義道義的始啊；為的，貫的，積重的，致好的的人或事物，君子的始啊。所以天地生君子，君子理天地；君子的人或事物，天地的參啊，萬物的摠啊，民的父母啊。無君子，則天地不理，禮正義道義道品德修養規程正義道義無統，上無君師，下無父子、夫婦，是的謂至亂。君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，這就是儒家所稱的大本。所以喪祭、朝聘、師旅一啊；貴賤、殺生、與奪一啊；君君、臣臣、父父、子子、兄兄、弟弟一啊；農農、士士、工工、商商一啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「以類行雜，以一行萬」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「以類行雜，以一行萬。始則終，終則始，若環之無端也，舍……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-19\",\"chapterId\":\"xunzi_ch-9\",\"order\":19,\"canonicalText\":\"水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也。力不若牛，走不若馬，而牛馬為用，何也？曰：人能羣，彼不能羣也。人何以能羣？曰：分。分何以能行？曰：義。故義以分則和，和則一，一則多力，多力則彊，彊則勝物；故宮室可得而居也。故序四時，裁萬物，兼利天下，無它故焉，得之分義也。\",\"sentenceIds\":[\"xunzi_ch-9_p-19_s-1\",\"xunzi_ch-9_p-19_s-2\",\"xunzi_ch-9_p-19_s-3\",\"xunzi_ch-9_p-19_s-4\",\"xunzi_ch-9_p-19_s-5\",\"xunzi_ch-9_p-19_s-6\",\"xunzi_ch-9_p-19_s-7\",\"xunzi_ch-9_p-19_s-8\",\"xunzi_ch-9_p-19_s-9\",\"xunzi_ch-9_p-19_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 19 節）中論述道：水火有氣而且無生，草木有生而且無知，禽獸有知而且無正義道義，人有氣、有生、有知，亦且有正義道義，所以最為天下貴啊。力不若牛，走不若馬，而且牛馬為用，何啊？說道：：人能羣，彼不能羣啊。人何以能羣？說道：：分。分何以能行？說道：：正義道義。所以正義道義以分則和，和則一，一則多力，多力則彊，彊則勝物；所以宮室可得而且居啊。所以序四時，裁萬物，兼利天下，無它所以焉，得的分正義道義啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「水火有氣而無生，草木有生而無知，禽獸有知而無義，人有……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-20\",\"chapterId\":\"xunzi_ch-9\",\"order\":20,\"canonicalText\":\"故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；故宮室不可得而居也，不可少頃舍禮義之謂也。能以事親謂之孝，能以事兄謂之弟，能以事上謂之順，能以使下謂之君。\",\"sentenceIds\":[\"xunzi_ch-9_p-20_s-1\",\"xunzi_ch-9_p-20_s-2\",\"xunzi_ch-9_p-20_s-3\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 20 節）中論述道：所以人生不能無羣，羣而且無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；所以宮室不可得而且居啊，不可少頃舍禮正義道義道品德修養規程正義道義的謂啊。能以事親謂的孝，能以事兄謂的弟，能以事上謂的順，能以使下謂的君。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 20 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-21\",\"chapterId\":\"xunzi_ch-9\",\"order\":21,\"canonicalText\":\"君者，善羣也。羣道當，則萬物皆得其宜，六畜皆得其長，羣生皆得其命。故養長時，則六畜育；殺生時，則草木殖；政令時，則百姓一，賢良服。\",\"sentenceIds\":[\"xunzi_ch-9_p-21_s-1\",\"xunzi_ch-9_p-21_s-2\",\"xunzi_ch-9_p-21_s-3\",\"xunzi_ch-9_p-21_s-4\",\"xunzi_ch-9_p-21_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 21 節）中論述道：君的人或事物，善羣啊。羣道當，則萬物皆得他的宜，六畜皆得他的長，羣生皆得他的命。所以養長時，則六畜育；殺生時，則草木殖；政令時，則百姓一，賢良服。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 21 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「君者，善羣也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「君者，善羣也。羣道當，則萬物皆得其宜，六畜皆得其長，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-22\",\"chapterId\":\"xunzi_ch-9\",\"order\":22,\"canonicalText\":\"聖主1之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也。黿鼉魚鱉鰍鱣孕別之時，罔罟毒藥不入澤，不夭其生，不絕其長也。春耕、夏耘、秋收、冬藏，四者不失時，故五穀不絕，而百姓有餘食也。汙池淵沼川澤，謹其時禁，故魚鱉優多，而百姓有餘用也。斬伐養長不失其時，故山林不童，而百姓有餘材也。\",\"sentenceIds\":[\"xunzi_ch-9_p-22_s-1\",\"xunzi_ch-9_p-22_s-2\",\"xunzi_ch-9_p-22_s-3\",\"xunzi_ch-9_p-22_s-4\",\"xunzi_ch-9_p-22_s-5\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 22 節）中論述道：聖主1的制啊：草木榮華滋碩的時，則斧斤不入山林，不夭他的生，不絕他的長啊。黿鼉魚鱉鰍鱣孕別的時，罔罟毒藥不入澤，不夭他的生，不絕他的長啊。春耕、夏耘、秋收、冬藏，四的人或事物不失時，所以五穀不絕，而且百姓有餘食啊。汙池淵沼川澤，謹他的時禁，所以魚鱉優多，而且百姓有餘用啊。斬伐養長不失他的時，所以山林不童，而且百姓有餘材啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 22 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「聖主1之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「聖主1之制也：草木榮華滋碩之時，則斧斤不入山林，不夭……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-23\",\"chapterId\":\"xunzi_ch-9\",\"order\":23,\"canonicalText\":\"聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約。故曰：一與一是為人者，謂之聖人也。\",\"sentenceIds\":[\"xunzi_ch-9_p-23_s-1\",\"xunzi_ch-9_p-23_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 23 節）中論述道：聖王的用啊：上察於天，下錯於地，塞備天地的間，加施萬物的上，微而且明，短而且長，狹而且廣，神明博大以至約。所以古聖先賢說道：：一與一是為人的人或事物，謂的聖人啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 23 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-24\",\"chapterId\":\"xunzi_ch-9\",\"order\":24,\"canonicalText\":\"序官：宰爵知賓客、祭祀、響食犧牲之牢數。司徒知百宗、城郭、立器之數。司馬知師旅、甲兵、乘白之數。脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師之事也。脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空之事也。相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而寡能，治田之事也。脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而財物不屈，虞師之事也。順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師之事也。論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師之事也。相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知其吉凶妖祥，傴巫跛擊之事也。脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而貨財通，治市之事也。抃急禁悍，防淫除邪，戮之以五刑，使暴悍以變，姦邪不作，司寇之事也。本政教，正法則，兼聽而時稽之，度其功勞，論其慶賞，以時慎脩，使百吏免盡，而眾庶不偷，冢宰之事也。論禮樂，正身行，廣教化，美風俗，兼覆而調一之，闢公之事也。全道德，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王之事也。故政事亂，則冢宰之罪也；國家失俗，則闢公之過也；天下不一，諸侯俗反，則天王非其人也。\",\"sentenceIds\":[\"xunzi_ch-9_p-24_s-1\",\"xunzi_ch-9_p-24_s-2\",\"xunzi_ch-9_p-24_s-3\",\"xunzi_ch-9_p-24_s-4\",\"xunzi_ch-9_p-24_s-5\",\"xunzi_ch-9_p-24_s-6\",\"xunzi_ch-9_p-24_s-7\",\"xunzi_ch-9_p-24_s-8\",\"xunzi_ch-9_p-24_s-9\",\"xunzi_ch-9_p-24_s-10\",\"xunzi_ch-9_p-24_s-11\",\"xunzi_ch-9_p-24_s-12\",\"xunzi_ch-9_p-24_s-13\",\"xunzi_ch-9_p-24_s-14\",\"xunzi_ch-9_p-24_s-15\",\"xunzi_ch-9_p-24_s-16\",\"xunzi_ch-9_p-24_s-17\",\"xunzi_ch-9_p-24_s-18\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 24 節）中論述道：序官：宰爵知賓客、祭祀、響食犧牲的牢數。司徒知百宗、城郭、立器的數。司馬知師旅、甲兵、乘白的數。脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師的事啊。脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空的事啊。相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而且寡能，治田的事啊。脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而且財物不屈，虞師的事啊。順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師的事啊。論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師的事啊。相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知他的吉凶妖祥，傴巫跛擊的事啊。脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而且貨財通，治市的事啊。抃急禁悍，防淫除邪，戮的以五刑，使暴悍以變，姦邪不作，司寇的事啊。本政教，正國家典章法度則，兼聽而且時稽的，度他的功勞，論他的慶賞，以時慎脩，使百吏免盡，而且眾庶不偷，冢宰的事啊。論禮正義道義道品德修養規程樂，正身行，廣教化，美風俗，兼覆而且調一的，闢公的事啊。全道品德修養，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王的事啊。所以政事亂，則冢宰的罪啊；國家失俗，則闢公的過啊；天下不一，諸侯俗反，則天王絕不是他的人啊。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 24 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「序官：宰爵知賓客、祭祀、響食犧牲之牢數」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「序官：宰爵知賓客、祭祀、響食犧牲之牢數。司徒知百宗、……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-25\",\"chapterId\":\"xunzi_ch-9\",\"order\":25,\"canonicalText\":\"具具而王，具具而霸，具具而存，具具而亡。用萬乘之國者，威彊之所以立也，名聲之所以美也，敵人之所以屈也，國之所以安危臧否也，制與在此，亡乎人。王、霸、安存、危殆、滅亡，制與在我，亡乎人。夫威彊未足以殆鄰敵也，名聲未足以縣天下也，則是國未能獨立也，豈渠得免夫累乎？天下脅於暴國，而黨為吾所不欲於是者，日與桀同事同行，無害為堯。是非功名之所就也，非存亡安危之所墮也。功名之所就，存亡安危之所墮，必將於愉殷赤心之所。誠以其國為王者之所亦王，以其國為危殆滅亡之所亦危殆滅亡。殷之日，案以中立，無有所偏，而為縱橫之事，偃然案兵無動，以觀夫暴國之相卒也。案平政教，審節奏，砥礪百姓，為是之日，而兵剸天下勁矣。案然修仁義，伉隆高，正法則，選賢良，養百姓，為是之日，而名聲剸天下之美矣。權者重之，兵者勁之，名聲者美之。夫堯舜者一天下也，不能加毫末於是矣。\",\"sentenceIds\":[\"xunzi_ch-9_p-25_s-1\",\"xunzi_ch-9_p-25_s-2\",\"xunzi_ch-9_p-25_s-3\",\"xunzi_ch-9_p-25_s-4\",\"xunzi_ch-9_p-25_s-5\",\"xunzi_ch-9_p-25_s-6\",\"xunzi_ch-9_p-25_s-7\",\"xunzi_ch-9_p-25_s-8\",\"xunzi_ch-9_p-25_s-9\",\"xunzi_ch-9_p-25_s-10\",\"xunzi_ch-9_p-25_s-11\",\"xunzi_ch-9_p-25_s-12\",\"xunzi_ch-9_p-25_s-13\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 25 節）中論述道：具具而且王，具具而且霸，具具而且存，具具而且亡。用萬乘的國的人或事物，威彊的所以立啊，名聲的所以美啊，敵人的所以屈啊，國的所以安危臧否啊，制與在此，亡乎人。王、霸、安存、危殆、滅亡，制與在我，亡乎人。夫威彊未足以殆鄰敵啊，名聲未足以縣天下啊，則是國未能獨立啊，豈渠得免夫累乎？天下脅於暴國，而且黨為吾所不欲於是的人或事物，日與桀同事同行，無害為堯。是絕不是功名的所就啊，絕不是存亡安危的所墮啊。功名的所就，存亡安危的所墮，必將於愉殷赤心的所。誠以他的國為王的人或事物的所亦王，以他的國為危殆滅亡的所亦危殆滅亡。殷的日，案以中立，無有所偏，而且為縱橫的事，偃然案兵無動，以觀夫暴國的相卒啊。案平政教，審節奏，砥礪百姓，為是的日，而且兵剸天下勁矣。案然修仁愛慈悲之德正義道義，伉隆高，正國家典章法度則，選賢良，養百姓，為是的日，而且名聲剸天下的美矣。權的人或事物重的，兵的人或事物勁的，名聲的人或事物美的。夫堯舜的人或事物一天下啊，不能加毫末於是矣。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 25 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「具具而王，具具而霸，具具而存，具具而亡」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「具具而王，具具而霸，具具而存，具具而亡。用萬乘之國者……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-9_p-26\",\"chapterId\":\"xunzi_ch-9\",\"order\":26,\"canonicalText\":\"權謀傾覆之人退，則賢良知聖之士案自進矣。刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。務本事，積財物，而勿忘棲遲薛越也，是使群臣百姓皆以制度行，則財物積，國家案自富矣。三者體此而天下服，暴國之君案自不能用其兵矣。何則？彼無與至也。彼其所與至者，必其民也。其民之親我也，歡若父母，好我芳如芝蘭，反顧其上則若灼黥，若仇讎；彼人之情性也雖桀蹠，豈有肯為其所惡，賊其所好者哉！彼以奪矣。故古之人，有以一國取天下者，非往行之也，脩政其所，莫不願，如是而可以誅暴禁悍矣。故周公南征而北國怨，曰：「何獨不來也！」東徵而西國怨，曰：「何獨後我也！」孰能有與是鬥者與？安以其國為是者王。殷之日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎之士，然後漸賞慶以先之，嚴刑罰以防之，擇士之知事者，使相率貫也，是以厭然畜積修飾，而物用之足也。兵革器械者，彼將日日暴露毀折之中原；我將脩飾之，拊循之，掩蓋之於府庫。貨財粟米者，彼將日日棲遲薛越之中野，我今將畜積並聚之於倉廩。材技股肱健勇爪牙之士，彼將日日挫頓竭之於仇敵，我今將來致之，並閱之，砥礪之於朝廷。如是，則彼日積敝，我日積完；彼日積貧，我日積富；彼日積勞，我日積佚。君臣上下之間者，彼將厲厲焉日日相離疾也，我將頓頓焉日日相親愛也，以是待其敝。安以其國為是者霸。立身則從傭俗，事行則遵傭故，進退貴賤則舉傭士，之所以接下之人百姓者則庸寬惠，如是者則安存。立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，之所以接下之人百姓者則好取侵奪，如是者危殆。立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐故，之所以接下之人百姓者，則好用其死力矣，而慢其功勞，好用其籍斂矣，而忘其本務，如是者滅亡。此五等者，不可不善擇也，王、霸、安存、危殆、滅亡之具也。善擇者制人，不善擇者人制之。善擇之者王，不善擇之者亡。夫王者之與亡者，制人之與人制之也，是其為相縣也亦遠矣。\",\"sentenceIds\":[\"xunzi_ch-9_p-26_s-1\",\"xunzi_ch-9_p-26_s-2\",\"xunzi_ch-9_p-26_s-3\",\"xunzi_ch-9_p-26_s-4\",\"xunzi_ch-9_p-26_s-5\",\"xunzi_ch-9_p-26_s-6\",\"xunzi_ch-9_p-26_s-7\",\"xunzi_ch-9_p-26_s-8\",\"xunzi_ch-9_p-26_s-9\",\"xunzi_ch-9_p-26_s-10\",\"xunzi_ch-9_p-26_s-11\",\"xunzi_ch-9_p-26_s-12\",\"xunzi_ch-9_p-26_s-13\",\"xunzi_ch-9_p-26_s-14\",\"xunzi_ch-9_p-26_s-15\",\"xunzi_ch-9_p-26_s-16\",\"xunzi_ch-9_p-26_s-17\",\"xunzi_ch-9_p-26_s-18\",\"xunzi_ch-9_p-26_s-19\",\"xunzi_ch-9_p-26_s-20\",\"xunzi_ch-9_p-26_s-21\",\"xunzi_ch-9_p-26_s-22\",\"xunzi_ch-9_p-26_s-23\",\"xunzi_ch-9_p-26_s-24\",\"xunzi_ch-9_p-26_s-25\",\"xunzi_ch-9_p-26_s-26\",\"xunzi_ch-9_p-26_s-27\",\"xunzi_ch-9_p-26_s-28\",\"xunzi_ch-9_p-26_s-29\",\"xunzi_ch-9_p-26_s-30\",\"xunzi_ch-9_p-26_s-31\",\"xunzi_ch-9_p-26_s-32\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【荀子白話通譯】在《荀子・王制》（第 26 節）中論述道：權謀傾覆的人退，則賢良知聖的士案自進矣。刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。務本事，積財物，而且勿忘棲遲薛越啊，是使群臣百姓皆以制度行，則財物積，國家案自富矣。三的人或事物體此而且天下服，暴國的君案自不能用他的兵矣。何則？彼無與至啊。彼他的所與至的人或事物，必他的民啊。他的民的親我啊，歡若父母，好我芳如芝蘭，反顧他的上則若灼黥，若仇讎；彼人的情性啊雖桀蹠，豈有肯為他的所惡，賊他的所好的人或事物哉！彼以奪矣。所以古的人，有以一國取天下的人或事物，絕不是往行的啊，脩政他的所，莫不願，如是而且可以誅暴禁悍矣。所以周公南征而且北國怨，說道：：何獨不來啊！東徵而且西國怨，說道：：何獨後我啊！孰能有與是鬥的人或事物與？安以他的國為是的人或事物王。殷的日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎的士，然後漸賞慶以先的，嚴刑罰以防的，擇士的知事的人或事物，使相率貫啊，是以厭然畜積修飾，而且物用的足啊。兵革器械的人或事物，彼將日日暴露毀折的中原；我將脩飾的，拊循的，掩蓋的於府庫。貨財粟米的人或事物，彼將日日棲遲薛越的中野，我今將畜積並聚的於倉廩。材技股肱健勇爪牙的士，彼將日日挫頓竭的於仇敵，我今將來致的，並閱的，砥礪的於朝廷。如是，則彼日積敝，我日積完；彼日積貧，我日積富；彼日積勞，我日積佚。君臣上下的間的人或事物，彼將厲厲焉日日相離疾啊，我將頓頓焉日日相親愛啊，以是待他的敝。安以他的國為是的人或事物霸。立身則從傭俗，事行則遵傭所以，進退貴賤則舉傭士，的所以接下的人百姓的人或事物則庸寬惠，如是的人或事物則安存。立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，的所以接下的人百姓的人或事物則好取侵奪，如是的人或事物危殆。立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐所以，的所以接下的人百姓的人或事物，則好用他的死力矣，而且慢他的功勞，好用他的籍斂矣，而且忘他的本務，如是的人或事物滅亡。此五等的人或事物，不可不善擇啊，王、霸、安存、危殆、滅亡的具啊。善擇的人或事物制人，不善擇的人或事物人制的。善擇的的人或事物王，不善擇的的人或事物亡。夫王的人或事物的與亡的人或事物，制人的與人制的啊，是他的為相縣啊亦遠矣。這段先秦儒學經典深刻論述了後天修習、隆禮重法、明分使羣與修身治國之理。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈王制〉（第 26 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「權謀傾覆之人退，則賢良知聖之士案自進矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「權謀傾覆之人退，則賢良知聖之士案自進矣。刑政平，百姓……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-9_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":1,\"canonicalText\":\"請問為政？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":2,\"canonicalText\":\"曰：賢能不待次而舉，罷不能不待須而廢，元惡不待教而誅，中庸雜民不待政而化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":3,\"canonicalText\":\"分未定也，則有昭繆也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":4,\"canonicalText\":\"雖王公士大夫之子孫也，不能屬於禮義，則歸之庶人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":5,\"canonicalText\":\"雖庶人之子孫也，積文學，正身行，能屬於禮義，則歸之卿相士大夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":6,\"canonicalText\":\"故姦言，姦說，姦事，姦能，遁逃反側之民，職而教之，須而待之，勉之以慶賞，懲之以刑罰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":7,\"canonicalText\":\"安職則畜，不安職則棄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":8,\"canonicalText\":\"五疾，上收而養之，材而事之，官施而衣食之，兼覆無遺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":9,\"canonicalText\":\"纔行反時者死無赦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-1_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-1\",\"order\":10,\"canonicalText\":\"夫是之謂天德，是王者之政也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-2\",\"order\":1,\"canonicalText\":\"聽政之大分：以善至者待之以禮，以不善至者待之以刑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-2\",\"order\":2,\"canonicalText\":\"兩者分別，則賢不肖不雜，是非不亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-2\",\"order\":3,\"canonicalText\":\"賢不肖不雜，則英傑至，是非不亂，則國家治。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-2\",\"order\":4,\"canonicalText\":\"若是，名聲日聞，天下願，令行禁止，王者之事畢矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":1,\"canonicalText\":\"凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":2,\"canonicalText\":\"若是，則大事殆乎弛，小事殆乎遂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":3,\"canonicalText\":\"和解調通，好假道人，而無所凝止之，則姦言並至，嘗試之說鋒起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":4,\"canonicalText\":\"若是，則聽大事煩，是又傷之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":5,\"canonicalText\":\"故法而不議，則法之所不至者必廢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":6,\"canonicalText\":\"職而不通，則職之所不及者必隊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":7,\"canonicalText\":\"故法而議，職而通，無隱謀，無遺善，而百事無過，非君子莫能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":8,\"canonicalText\":\"故公平者，聽1之衡也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":9,\"canonicalText\":\"中和者，聽之繩也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":10,\"canonicalText\":\"其有法者以法行，無法者以類舉，聽之盡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":11,\"canonicalText\":\"偏黨而不經，聽之闢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":12,\"canonicalText\":\"故有良法而亂者，有之矣，有君子而亂者，自古及今，未嘗聞也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":13,\"canonicalText\":\"傳曰：「治生乎君子，亂生乎小人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-3_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-3\",\"order\":14,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":1,\"canonicalText\":\"分均則不偏，埶齊則不壹，眾齊則不使。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":2,\"canonicalText\":\"有天有地，而上下有差；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":3,\"canonicalText\":\"明王始立，而處國有制。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":4,\"canonicalText\":\"夫兩貴之不能相事，兩賤之不能相使，是天數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":5,\"canonicalText\":\"埶位齊，而欲惡同，物不能澹則必爭；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":6,\"canonicalText\":\"爭則必亂，亂則窮矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":7,\"canonicalText\":\"先王惡其亂也，故制禮義以分之，使有貧富貴賤之等，足以相兼臨者，是養天下之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":8,\"canonicalText\":\"《書》曰：「維齊非齊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-4_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-4\",\"order\":9,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":1,\"canonicalText\":\"馬駭輿，則君子不安輿；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":2,\"canonicalText\":\"庶人駭政，則君子不安位。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":3,\"canonicalText\":\"馬駭輿，則莫若靜之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":4,\"canonicalText\":\"庶人駭政，則莫若惠之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":5,\"canonicalText\":\"選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":6,\"canonicalText\":\"如是，則庶人安政矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":7,\"canonicalText\":\"庶人安政，然後君子安位。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":8,\"canonicalText\":\"傳曰：「君者、舟也，庶人者、水也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":9,\"canonicalText\":\"水則載舟，水則覆舟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":10,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":11,\"canonicalText\":\"故君人者，欲安、則莫若平政愛民矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":12,\"canonicalText\":\"欲榮、則莫若隆禮敬士矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":13,\"canonicalText\":\"欲立功名、則莫若尚賢使能矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":14,\"canonicalText\":\"－是人君之大節也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":15,\"canonicalText\":\"三節者當，則其餘莫不當矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":16,\"canonicalText\":\"三節者不當，則其餘雖曲當，猶將無益也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":17,\"canonicalText\":\"孔子曰：「大節是也，小節是也，上君也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":18,\"canonicalText\":\"大節是也，小節一齣焉，一入焉，中君也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":19,\"canonicalText\":\"大節非也，小節雖是也，吾無觀其餘矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-5_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-5\",\"order\":20,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":1,\"canonicalText\":\"成侯、嗣公聚斂計數之君也，未及取民也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":2,\"canonicalText\":\"子產取民者也，未及為政也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":3,\"canonicalText\":\"管仲為政者也，未及修禮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":4,\"canonicalText\":\"故修禮者王，為政者彊，取民者安，聚斂者亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":5,\"canonicalText\":\"故王者富民，霸者富士，僅存之國富大夫，亡國富筐篋，實府庫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":6,\"canonicalText\":\"筐篋已富，府庫已實，而百姓貧：夫是之謂上溢而下漏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":7,\"canonicalText\":\"入不可以守，出不可以戰，則傾覆滅亡可立而待也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":8,\"canonicalText\":\"故我聚之以亡，敵得之以彊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-6_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-6\",\"order\":9,\"canonicalText\":\"聚斂者，召寇、肥敵、亡國、危身之道也，故明君不蹈也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-7\",\"order\":1,\"canonicalText\":\"王奪之人，霸奪之與，彊奪之地。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-7\",\"order\":2,\"canonicalText\":\"奪之人者臣諸侯，奪之與者友諸侯，奪之地者敵諸侯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-7\",\"order\":3,\"canonicalText\":\"臣諸侯者王，友諸侯者霸，敵諸侯者危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":1,\"canonicalText\":\"用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":2,\"canonicalText\":\"傷人之民甚，則人之民必惡我甚矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":3,\"canonicalText\":\"人之民惡我甚，則日欲與我鬥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":4,\"canonicalText\":\"人之城守，人之出戰，而我以力勝之，則傷吾民必甚矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":5,\"canonicalText\":\"傷吾民甚，則吾民之惡我必甚矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":6,\"canonicalText\":\"吾民之惡我甚，則日不欲為我鬥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":7,\"canonicalText\":\"人之民日欲與我鬥，吾民日不欲為我鬥，是彊者之所以反弱也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":8,\"canonicalText\":\"地來而民去，累多而功少，雖守者益，所以守者損，是以大者之所以反削也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-8_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-8\",\"order\":9,\"canonicalText\":\"諸侯莫不懷交接怨，而不忘其敵，伺彊大之間，承彊大之敝，此彊大之殆時也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-9\",\"order\":1,\"canonicalText\":\"知彊大者不務彊也，慮以王命，全其力，凝其德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-9\",\"order\":2,\"canonicalText\":\"力全則諸侯不能弱也，德凝則諸侯不能削也，天下無王霸主，則常勝矣：是知彊道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":1,\"canonicalText\":\"彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":2,\"canonicalText\":\"存亡繼絕，衛弱禁暴，而無兼併之心，則諸侯親之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":3,\"canonicalText\":\"修友敵之道，以敬接諸侯，則諸侯說之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":4,\"canonicalText\":\"所以親之者，以不併也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":5,\"canonicalText\":\"並之見，則諸侯疏矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":6,\"canonicalText\":\"所以說之者，以友敵也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":7,\"canonicalText\":\"臣之見，則諸侯離矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":8,\"canonicalText\":\"故明其不併之行，信其友敵之道，天下無王霸主，則常勝矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-10_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-10\",\"order\":9,\"canonicalText\":\"是知霸道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-11\",\"order\":1,\"canonicalText\":\"閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":1,\"canonicalText\":\"彼王者不然：仁眇天下，義眇天下，威眇天下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":2,\"canonicalText\":\"仁眇天下，故天下莫不親也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":3,\"canonicalText\":\"義眇天下，故天下莫不貴也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":4,\"canonicalText\":\"威眇天下，故天下莫敢敵也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":5,\"canonicalText\":\"以不敵之威，輔服人之道，故不戰而勝，不攻而得，甲兵不勞而天下服，是知王道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-12\",\"order\":6,\"canonicalText\":\"知此三具者，欲王而王，欲霸而霸，欲彊而彊矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-13\",\"order\":1,\"canonicalText\":\"王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-13\",\"order\":2,\"canonicalText\":\"是王者之人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-14\",\"order\":1,\"canonicalText\":\"王者之制：道不過三代，法不二後王；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-14\",\"order\":2,\"canonicalText\":\"道過三代謂之蕩，法二後王謂之不雅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-14\",\"order\":3,\"canonicalText\":\"衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-14\",\"order\":4,\"canonicalText\":\"聲、則非雅聲者舉廢，色、則凡非舊文者舉息，械用，則凡非舊器者舉毀，夫是之謂復古，是王者之制也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":1,\"canonicalText\":\"王者之論：無德不貴，無能不官，無功不賞，無罪不罰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":2,\"canonicalText\":\"朝無幸位，民無幸生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":3,\"canonicalText\":\"尚賢使能，而等位不遺；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":4,\"canonicalText\":\"析願禁悍，而刑罰不過。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":5,\"canonicalText\":\"百姓曉然皆知夫為善於家，而取賞於朝也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":6,\"canonicalText\":\"為不善於幽，而蒙刑於顯也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":7,\"canonicalText\":\"夫是之謂定論。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-15_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-15\",\"order\":8,\"canonicalText\":\"是王者之論也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":1,\"canonicalText\":\"王者之法1：等賦、政事、財萬物，所以養萬民也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":2,\"canonicalText\":\"田野什一，關市幾而不徵，山林澤梁，以時禁發而不稅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":3,\"canonicalText\":\"相地而衰政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":4,\"canonicalText\":\"理道之遠近而致貢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":5,\"canonicalText\":\"通流財物粟米，無有滯留，使相歸移也，四海之內若一家。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":6,\"canonicalText\":\"故近者不隱其能，遠者不疾其勞，無幽閒隱僻之國，莫不趨使而安樂之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":7,\"canonicalText\":\"夫是之為人師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-16_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-16\",\"order\":8,\"canonicalText\":\"是王者之法也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":1,\"canonicalText\":\"北海則有走馬吠犬焉，然而中國得而畜使之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":2,\"canonicalText\":\"南海則有羽翮、齒革、曾青、丹干焉，然而中國得而財之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":3,\"canonicalText\":\"東海則有紫紶、魚鹽焉，然而中國得而衣食之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":4,\"canonicalText\":\"西海則有皮革、文旄焉，然而中國得而用之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":5,\"canonicalText\":\"故澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而足械用，工賈不耕田而足菽粟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":6,\"canonicalText\":\"故虎豹為猛矣，然君子剝而用之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":7,\"canonicalText\":\"故天之所覆，地之所載，莫不盡其美，致其用，上以飾賢良，下以養百姓而安樂之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":8,\"canonicalText\":\"夫是之謂大神。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":9,\"canonicalText\":\"《詩》曰：「天作高山，大王荒之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":10,\"canonicalText\":\"彼作矣，文王康之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-17_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-17\",\"order\":11,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":1,\"canonicalText\":\"以類行雜，以一行萬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":2,\"canonicalText\":\"始則終，終則始，若環之無端也，舍是而天下以衰矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":3,\"canonicalText\":\"天地者，生之始也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":4,\"canonicalText\":\"禮義者，治之始也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":5,\"canonicalText\":\"君子者，禮義之始也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":6,\"canonicalText\":\"為之，貫之，積重之，致好之者，君子之始也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":7,\"canonicalText\":\"故天地生君子，君子理天地；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":8,\"canonicalText\":\"君子者，天地之參也，萬物之摠也，民之父母也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":9,\"canonicalText\":\"無君子，則天地不理，禮義無統，上無君師，下無父子、夫婦，是之謂至亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":10,\"canonicalText\":\"君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，夫是之謂大本。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":11,\"canonicalText\":\"故喪祭、朝聘、師旅一也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":12,\"canonicalText\":\"貴賤、殺生、與奪一也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":13,\"canonicalText\":\"君君、臣臣、父父、子子、兄兄、弟弟一也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-18_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-18\",\"order\":14,\"canonicalText\":\"農農、士士、工工、商商一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":1,\"canonicalText\":\"水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":2,\"canonicalText\":\"力不若牛，走不若馬，而牛馬為用，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":3,\"canonicalText\":\"曰：人能羣，彼不能羣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":4,\"canonicalText\":\"人何以能羣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":5,\"canonicalText\":\"曰：分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":6,\"canonicalText\":\"分何以能行？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":7,\"canonicalText\":\"曰：義。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":8,\"canonicalText\":\"故義以分則和，和則一，一則多力，多力則彊，彊則勝物；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":9,\"canonicalText\":\"故宮室可得而居也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-19_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-19\",\"order\":10,\"canonicalText\":\"故序四時，裁萬物，兼利天下，無它故焉，得之分義也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-20_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-20\",\"order\":1,\"canonicalText\":\"故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-20_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-20\",\"order\":2,\"canonicalText\":\"故宮室不可得而居也，不可少頃舍禮義之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-20_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-20\",\"order\":3,\"canonicalText\":\"能以事親謂之孝，能以事兄謂之弟，能以事上謂之順，能以使下謂之君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-21_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-21\",\"order\":1,\"canonicalText\":\"君者，善羣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-21_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-21\",\"order\":2,\"canonicalText\":\"羣道當，則萬物皆得其宜，六畜皆得其長，羣生皆得其命。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-21_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-21\",\"order\":3,\"canonicalText\":\"故養長時，則六畜育；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-21_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-21\",\"order\":4,\"canonicalText\":\"殺生時，則草木殖；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-21_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-21\",\"order\":5,\"canonicalText\":\"政令時，則百姓一，賢良服。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-22_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-22\",\"order\":1,\"canonicalText\":\"聖主1之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-22_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-22\",\"order\":2,\"canonicalText\":\"黿鼉魚鱉鰍鱣孕別之時，罔罟毒藥不入澤，不夭其生，不絕其長也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-22_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-22\",\"order\":3,\"canonicalText\":\"春耕、夏耘、秋收、冬藏，四者不失時，故五穀不絕，而百姓有餘食也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-22_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-22\",\"order\":4,\"canonicalText\":\"汙池淵沼川澤，謹其時禁，故魚鱉優多，而百姓有餘用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-22_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-22\",\"order\":5,\"canonicalText\":\"斬伐養長不失其時，故山林不童，而百姓有餘材也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-23_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-23\",\"order\":1,\"canonicalText\":\"聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-23_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-23\",\"order\":2,\"canonicalText\":\"故曰：一與一是為人者，謂之聖人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":1,\"canonicalText\":\"序官：宰爵知賓客、祭祀、響食犧牲之牢數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":2,\"canonicalText\":\"司徒知百宗、城郭、立器之數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":3,\"canonicalText\":\"司馬知師旅、甲兵、乘白之數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":4,\"canonicalText\":\"脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":5,\"canonicalText\":\"脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":6,\"canonicalText\":\"相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而寡能，治田之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":7,\"canonicalText\":\"脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而財物不屈，虞師之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":8,\"canonicalText\":\"順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":9,\"canonicalText\":\"論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":10,\"canonicalText\":\"相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知其吉凶妖祥，傴巫跛擊之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":11,\"canonicalText\":\"脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而貨財通，治市之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":12,\"canonicalText\":\"抃急禁悍，防淫除邪，戮之以五刑，使暴悍以變，姦邪不作，司寇之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":13,\"canonicalText\":\"本政教，正法則，兼聽而時稽之，度其功勞，論其慶賞，以時慎脩，使百吏免盡，而眾庶不偷，冢宰之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":14,\"canonicalText\":\"論禮樂，正身行，廣教化，美風俗，兼覆而調一之，闢公之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":15,\"canonicalText\":\"全道德，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":16,\"canonicalText\":\"故政事亂，則冢宰之罪也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":17,\"canonicalText\":\"國家失俗，則闢公之過也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-24_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-24\",\"order\":18,\"canonicalText\":\"天下不一，諸侯俗反，則天王非其人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":1,\"canonicalText\":\"具具而王，具具而霸，具具而存，具具而亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":2,\"canonicalText\":\"用萬乘之國者，威彊之所以立也，名聲之所以美也，敵人之所以屈也，國之所以安危臧否也，制與在此，亡乎人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":3,\"canonicalText\":\"王、霸、安存、危殆、滅亡，制與在我，亡乎人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":4,\"canonicalText\":\"夫威彊未足以殆鄰敵也，名聲未足以縣天下也，則是國未能獨立也，豈渠得免夫累乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":5,\"canonicalText\":\"天下脅於暴國，而黨為吾所不欲於是者，日與桀同事同行，無害為堯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":6,\"canonicalText\":\"是非功名之所就也，非存亡安危之所墮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":7,\"canonicalText\":\"功名之所就，存亡安危之所墮，必將於愉殷赤心之所。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":8,\"canonicalText\":\"誠以其國為王者之所亦王，以其國為危殆滅亡之所亦危殆滅亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":9,\"canonicalText\":\"殷之日，案以中立，無有所偏，而為縱橫之事，偃然案兵無動，以觀夫暴國之相卒也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":10,\"canonicalText\":\"案平政教，審節奏，砥礪百姓，為是之日，而兵剸天下勁矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":11,\"canonicalText\":\"案然修仁義，伉隆高，正法則，選賢良，養百姓，為是之日，而名聲剸天下之美矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":12,\"canonicalText\":\"權者重之，兵者勁之，名聲者美之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-25_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-25\",\"order\":13,\"canonicalText\":\"夫堯舜者一天下也，不能加毫末於是矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":1,\"canonicalText\":\"權謀傾覆之人退，則賢良知聖之士案自進矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":2,\"canonicalText\":\"刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":3,\"canonicalText\":\"務本事，積財物，而勿忘棲遲薛越也，是使群臣百姓皆以制度行，則財物積，國家案自富矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":4,\"canonicalText\":\"三者體此而天下服，暴國之君案自不能用其兵矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":5,\"canonicalText\":\"何則？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":6,\"canonicalText\":\"彼無與至也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":7,\"canonicalText\":\"彼其所與至者，必其民也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":8,\"canonicalText\":\"其民之親我也，歡若父母，好我芳如芝蘭，反顧其上則若灼黥，若仇讎；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":9,\"canonicalText\":\"彼人之情性也雖桀蹠，豈有肯為其所惡，賊其所好者哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":10,\"canonicalText\":\"彼以奪矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":11,\"canonicalText\":\"故古之人，有以一國取天下者，非往行之也，脩政其所，莫不願，如是而可以誅暴禁悍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":12,\"canonicalText\":\"故周公南征而北國怨，曰：「何獨不來也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":13,\"canonicalText\":\"」東徵而西國怨，曰：「何獨後我也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":14,\"canonicalText\":\"」孰能有與是鬥者與？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":15,\"canonicalText\":\"安以其國為是者王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":16,\"canonicalText\":\"殷之日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎之士，然後漸賞慶以先之，嚴刑罰以防之，擇士之知事者，使相率貫也，是以厭然畜積修飾，而物用之足也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":17,\"canonicalText\":\"兵革器械者，彼將日日暴露毀折之中原；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":18,\"canonicalText\":\"我將脩飾之，拊循之，掩蓋之於府庫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":19,\"canonicalText\":\"貨財粟米者，彼將日日棲遲薛越之中野，我今將畜積並聚之於倉廩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":20,\"canonicalText\":\"材技股肱健勇爪牙之士，彼將日日挫頓竭之於仇敵，我今將來致之，並閱之，砥礪之於朝廷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":21,\"canonicalText\":\"如是，則彼日積敝，我日積完；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":22,\"canonicalText\":\"彼日積貧，我日積富；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":23,\"canonicalText\":\"彼日積勞，我日積佚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":24,\"canonicalText\":\"君臣上下之間者，彼將厲厲焉日日相離疾也，我將頓頓焉日日相親愛也，以是待其敝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":25,\"canonicalText\":\"安以其國為是者霸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":26,\"canonicalText\":\"立身則從傭俗，事行則遵傭故，進退貴賤則舉傭士，之所以接下之人百姓者則庸寬惠，如是者則安存。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":27,\"canonicalText\":\"立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，之所以接下之人百姓者則好取侵奪，如是者危殆。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":28,\"canonicalText\":\"立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐故，之所以接下之人百姓者，則好用其死力矣，而慢其功勞，好用其籍斂矣，而忘其本務，如是者滅亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":29,\"canonicalText\":\"此五等者，不可不善擇也，王、霸、安存、危殆、滅亡之具也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-30\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":30,\"canonicalText\":\"善擇者制人，不善擇者人制之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-31\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":31,\"canonicalText\":\"善擇之者王，不善擇之者亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-9_p-26_s-32\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-9\",\"passageId\":\"xunzi_ch-9_p-26\",\"order\":32,\"canonicalText\":\"夫王者之與亡者，制人之與人制之也，是其為相縣也亦遠矣。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
